import { useBooking } from '../../../hooks/useBooking';
import { StepCard }   from '../../StepCard';

const ASSETS_URL = window.hwBooking?.assetsUrl ?? '';

const CARD_TYPES = [
	{ value: 'visa', label: 'Visa',            img: 'visa.png' },
	{ value: 'mc',   label: 'Mastercard',       img: 'mc.png'   },
	{ value: 'amex', label: 'American Express', img: 'amex.png' },
];

function detectCardType( digits ) {
	if ( /^4/.test( digits ) )                                          return 'visa';
	if ( /^3[47]/.test( digits ) )                                      return 'amex';
	if ( /^5[1-5]/.test( digits ) || /^2[2-7]/.test( digits ) )        return 'mc';
	return null;
}

function formatCardNumber( digits, isAmex ) {
	if ( ! digits ) return '';
	if ( isAmex ) {
		return [ digits.slice( 0, 4 ), digits.slice( 4, 10 ), digits.slice( 10, 15 ) ]
			.filter( Boolean ).join( ' ' );
	}
	return digits.match( /.{1,4}/g )?.join( ' ' ) ?? '';
}

function expiryDisplay( month, year ) {
	if ( ! month ) return '';
	return year ? `${ month } / ${ year }` : month;
}

export default function CardDetailsCard( { errors = {}, payableAmount } ) {
	const { payment, dispatch } = useBooking();

	const cardType  = payment.cardType ?? 'visa';
	const isAmex    = cardType === 'amex';
	const cvvLength = isAmex ? 4 : 3;

	function set( field ) {
		return ( e ) => dispatch( { type: 'SET_PAYMENT', payload: { [ field ]: e.target.value } } );
	}
	function setDirect( field, value ) {
		dispatch( { type: 'SET_PAYMENT', payload: { [ field ]: value } } );
	}

	function handleCardNumberChange( e ) {
		const raw      = e.target.value.replace( /\D/g, '' );
		const detected = detectCardType( raw );
		const newType  = detected ?? cardType;
		const digits   = raw.slice( 0, newType === 'amex' ? 15 : 16 );
		if ( detected && detected !== cardType ) {
			dispatch( { type: 'SET_PAYMENT', payload: { cardType: detected, cvv: '' } } );
		}
		setDirect( 'cardNumber', digits );
	}

	function handleExpiryChange( e ) {
		const digits = e.target.value.replace( /\D/g, '' ).slice( 0, 6 );
		dispatch( { type: 'SET_PAYMENT', payload: {
			cardMonth: digits.slice( 0, 2 ),
			cardYear:  digits.slice( 2, 6 ),
		} } );
	}

	function fc( key ) {
		return `form-control${ errors[ key ] ? ' is-invalid' : '' }`;
	}

	return (
		<StepCard className="mb-3">
			<StepCard.Header icon="fas fa-credit-card" title="Card Details" />

			{ /* Card type logos */ }
			<div className="form-group">
				<div className="d-flex gap-2">
					{ CARD_TYPES.map( ( { value, label, img } ) => {
						const active = cardType === value;
						return (
							<label
								key={ value }
								className={ `pay-card-type${ active ? ' pay-card-type--active' : '' }` }
								title={ label }
							>
								<input
									type="radio"
									name="cardType"
									value={ value }
									checked={ active }
									onChange={ () => { setDirect( 'cardType', value ); setDirect( 'cvv', '' ); } }
									className="sr-only"
								/>
								<img src={ `${ ASSETS_URL }/img/${ img }` } alt={ label } className="pay-card-img" />
							</label>
						);
					} ) }
				</div>
			</div>

			{ /* Card number + expiry + CVV */ }
			<div className="form-row">
				<div className="form-group col-md-6">
					<label>Card Number</label>
					<div className="pay-input-wrap">
						<i className="fas fa-credit-card pay-input-icon" />
						<input
							type="text"
							inputMode="numeric"
							className={ `${ fc( 'cardNumber' ) } pay-input--icon` }
							value={ formatCardNumber( payment.cardNumber ?? '', isAmex ) }
							onChange={ handleCardNumberChange }
							placeholder={ isAmex ? '•••• •••••• •••••' : '•••• •••• •••• ••••' }
							autoComplete="cc-number"
						/>
					</div>
					{ errors.cardNumber && <div className="invalid-feedback d-block">{ errors.cardNumber }</div> }
				</div>

				<div className="form-group col-md-3">
					<label>Expiration Date</label>
					<div className="pay-input-wrap">
						<i className="fas fa-calendar-alt pay-input-icon" />
						<input
							type="text"
							inputMode="numeric"
							className={ `form-control pay-input--icon${ errors.expiry ? ' is-invalid' : '' }` }
							value={ expiryDisplay( payment.cardMonth ?? '', payment.cardYear ?? '' ) }
							onChange={ handleExpiryChange }
							placeholder="MM / YYYY"
							autoComplete="cc-exp"
						/>
					</div>
					{ errors.expiry && <div className="invalid-feedback d-block">{ errors.expiry }</div> }
				</div>

				<div className="form-group col-md-3">
					<label>{ isAmex ? 'CID' : 'CVV' }</label>
					<div className="pay-input-wrap">
						<i className="fas fa-lock pay-input-icon" />
						<input
							type="text"
							inputMode="numeric"
							className={ `${ fc( 'cvv' ) } pay-input--icon` }
							placeholder={ isAmex ? '••••' : '•••' }
							value={ payment.cvv ?? '' }
							onChange={ ( e ) => {
								const val = e.target.value.replace( /\D/g, '' );
								if ( val.length <= cvvLength ) setDirect( 'cvv', val );
							} }
							autoComplete="cc-csc"
						/>
					</div>
					{ errors.cvv && <div className="invalid-feedback d-block">{ errors.cvv }</div> }
				</div>
			</div>

			{ /* Card owner — full width, last */ }
			<div className="form-group">
				<label>Card Owner</label>
				<input
					type="text"
					className={ fc( 'cardOwner' ) }
					value={ payment.cardOwner ?? '' }
					onChange={ set( 'cardOwner' ) }
					autoComplete="cc-name"
				/>
				{ errors.cardOwner && <div className="invalid-feedback">{ errors.cardOwner }</div> }
			</div>

			{ /* Disclaimer + authorization */ }
			<div className="callout callout--primary" role="alert">
				<div>
					<div className="pay-disclaimer mb-0">
						By submitting, you certify that you are the cardholder and are authorizing the travel agency
						or its chosen Tour Operator/Supplier to charge the listed amount to the credit card. You certify
						that you have verified that all information contained in the confirmation you received is accurate.
						You also certify you have read the Terms &amp; Conditions and the appropriate Travel Protection Plan
						details. Cancellation penalties may apply. Insurance is not refundable.
						<br /><br />
						This charge will be manually applied by the agency to your reservation. If there are any issues,
						an agent will get back to you. Please note that you may not see a charge from the travel agency on
						your credit card statement; the charge will come from our supplier directly. Payment may take 3–5
						business days to fully process and be reflected on your statement.
					</div>
					<label
						htmlFor="pay-accept"
						className={ `border pay-auth${ payment.acceptCharge ? ' pay-auth--checked' : '' }${ errors.acceptCharge ? ' pay-auth--error' : '' }` }
					>
						<input
							type="checkbox"
							id="pay-accept"
							className="sr-only"
							checked={ Boolean( payment.acceptCharge ) }
							onChange={ ( e ) => setDirect( 'acceptCharge', e.target.checked ) }
						/>
						<span className={ `pay-auth__box${ ! payment.acceptCharge ? ' pay-auth__box--pulse' : '' }` }>
							{ payment.acceptCharge && <i className="fas fa-check pay-auth__check" /> }
						</span>
						<span className="pay-auth__text">
							I authorize Hola Weddings to charge my card for the amount of{ ' ' }
							<strong>{ payableAmount }</strong>.
						</span>
					</label>
					{ errors.acceptCharge && (
						<div className="pay-auth__error">{ errors.acceptCharge }</div>
					) }
				</div>
			</div>
		</StepCard>
	);
}
