/**
 * @param {object}  props
 * @param {string}  [props.variant]       - Visual style: 'primary', 'danger', 'outline-primary', etc. → adds btn-{variant}
 * @param {string}  [props.icon]          - Font Awesome classes, e.g. 'fas fa-arrow-right'
 * @param {string}  [props.iconPosition]  - 'left' | 'right' (default 'right')
 * @param {string}  [props.justify]       - flex justify-content when icon present (default 'space-between')
 * @param {string}  [props.className]     - extra classes
 * @param {*}       [props.children]
 * @param {object}  [...props]            - all native <button> attributes (type, onClick, disabled, …)
 */
export default function Button( {
	children,
	variant,
	icon,
	iconPosition = 'right',
	justify      = 'space-between',
	className    = '',
	...props
} ) {
	const cls = [ 'btn', variant && `btn-${ variant }`, icon && 'btn--with-icon', className ]
		.filter( Boolean )
		.join( ' ' );

	if ( ! icon ) {
		return (
			<button className={ cls } style={ { textAlign: 'center' } } { ...props }>
				{ children }
			</button>
		);
	}

	const iconEl = <i className={ icon } />;

	return (
		<button
			className={ cls }
			style={ { display: 'flex', alignItems: 'center', justifyContent: justify, gap: '0.5rem' } }
			{ ...props }
		>
			{ iconPosition === 'left'  && iconEl }
			{ children }
			{ iconPosition === 'right' && iconEl }
		</button>
	);
}
