import { useState } from '@wordpress/element';
import { useCart } from '../../hooks/useCart';
import { useBooking } from '../../store/bookingContext';

export default function MobileSummary() {
	const { selectedRoom, selectedPackage } = useBooking();
	const { grandTotal, deposit } = useCart();
	const [ open, setOpen ] = useState( false );

	const product = selectedRoom ?? selectedPackage;
	const sym = window.hwBooking?.currencySymbol ?? '$';

	if ( ! product ) return null;

	return (
		<div className="d-lg-none card p-3 mb-3">
			<button
				type="button"
				className="btn btn-link p-0 d-flex justify-content-between w-100"
				onClick={ () => setOpen( ( o ) => ! o ) }
			>
				<span>{ product.name }</span>
				<span>{ sym }{ grandTotal } { open ? '▲' : '▼' }</span>
			</button>

			{ open && (
				<div className="mt-2">
					<div className="d-flex justify-content-between text-muted">
						<span>Today you pay</span>
						<span>{ sym }{ deposit }</span>
					</div>
				</div>
			) }
		</div>
	);
}
