import { useState, useRef, useEffect } from '@wordpress/element';
import { useBooking } from '../hooks/useBooking';

// ── Locale objects (mirrors cart.js datepickerEnLocale / datepickerEsLocale) ──
const EN_LOCALE = {
	days:        [ 'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday' ],
	daysShort:   [ 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat' ],
	daysMin:     [ 'Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa' ],
	months:      [ 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December' ],
	monthsShort: [ 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec' ],
	today:       'Today',
	clear:       'Clear',
	dateFormat:  'MM/dd/yyyy',
	firstDay:    0,
};

const ES_LOCALE = {
	days:        [ 'Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado' ],
	daysShort:   [ 'Dom', 'Lun', 'Mar', 'Mie', 'Jue', 'Vie', 'Sab' ],
	daysMin:     [ 'Do', 'Lu', 'Ma', 'Mi', 'Ju', 'Vi', 'Sa' ],
	months:      [ 'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre' ],
	monthsShort: [ 'Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic' ],
	today:       'Hoy',
	clear:       'Limpiar',
	dateFormat:  'dd/MM/yyyy',
	firstDay:    1,
};

// ── Helpers (mirrors ymdToLocalDate / addDays / removeDays in cart.js) ────────
function ymdToLocalDate( ymd ) {
	const [ y, m, d ] = ymd.split( '-' );
	return new Date( Number( y ), Number( m ) - 1, Number( d ) );
}

function addDays( date, days ) {
	const d = new Date( date );
	d.setDate( d.getDate() + days );
	return d;
}

// ── Guest helpers ─────────────────────────────────────────────────────────────
const _isTeenEnabled = Boolean( window.hwBooking?.isTeenEnabled );

const GUEST_TYPES = [
	{ field: 'adults',   label: 'Adults',   desc: '18+ years',   min: 1 },
	...( _isTeenEnabled ? [ { field: 'teens', label: 'Teens', desc: '13–17 years', min: 0 } ] : [] ),
	{ field: 'children', label: 'Children', desc: '2–12 years',  min: 0 },
	{ field: 'infants',  label: 'Infants',  desc: 'Under 2',     min: 0 },
];

function formatDate( dateStr ) {
	if ( ! dateStr ) return null;
	const [ y, m, d ] = dateStr.split( '-' );
	return new Date( y, m - 1, d ).toLocaleDateString( 'en-US', {
		month: 'short', day: 'numeric', year: 'numeric',
	} );
}

function guestSummary( search ) {
	const parts = [];
	if ( search.adults   > 0 ) parts.push( `${ search.adults } Adult${ search.adults !== 1 ? 's' : '' }` );
	if ( search.teens    > 0 ) parts.push( `${ search.teens } Teen${ search.teens !== 1 ? 's' : '' }` );
	if ( search.children > 0 ) parts.push( `${ search.children } Child${ search.children !== 1 ? 'ren' : '' }` );
	if ( search.infants  > 0 ) parts.push( `${ search.infants } Infant${ search.infants !== 1 ? 's' : '' }` );
	return parts.join( ', ' ) || 'Add guests';
}

function toYmd( date ) {
	const y = date.getFullYear();
	const m = String( date.getMonth() + 1 ).padStart( 2, '0' );
	const d = String( date.getDate() ).padStart( 2, '0' );
	return `${ y }-${ m }-${ d }`;
}

const HOTEL_NAME = window.hwBooking?.hotelName ?? 'Hotel';

// ── Component ─────────────────────────────────────────────────────────────────
export default function SearchBox() {
	const { search, dispatch } = useBooking();
	const [ guestsOpen,      setGuestsOpen      ] = useState( false );
	const [ checkoutError,   setCheckoutError   ] = useState( null );
	const [ submitAttempted, setSubmitAttempted ] = useState( false );
	const [ mobileOpen,      setMobileOpen      ] = useState( false );

	// Derived per-field validity — reactive: clears automatically when fixed
	const checkinInvalid  = submitAttempted && ! search.checkin;
	const checkoutInvalid = submitAttempted && ! search.checkout;
	const guestsInvalid   = submitAttempted && ( search.adults || 0 ) < 1;

	const dpInRef          = useRef( null );  // AirDatepicker check-in instance
	const dpOutRef         = useRef( null );  // AirDatepicker check-out instance
	const checkinAnchorRef  = useRef( null ); // hidden input in check-in field
	const checkoutAnchorRef = useRef( null ); // hidden input in check-out field
	const guestsRef         = useRef( null );

	// ── Datepicker init (mirrors cart.js logic) ───────────────────────────────
	useEffect( () => {
		if ( ! window.AirDatepicker || ! checkinAnchorRef.current || ! checkoutAnchorRef.current ) return;

		const hw       = window.hw       ?? {};
		const hwCart   = window[ 'hw_cart' ]  ?? {};
		const minNight = parseInt( hwCart.min_nights ?? 1 );
		const locale   = document.documentElement.lang?.startsWith( 'es' ) ? ES_LOCALE : EN_LOCALE;

		// Mirror: start_date = ymdToLocalDate(hw.start_date)
		const startDate = hw.start_date ? ymdToLocalDate( hw.start_date ) : new Date();
		// Mirror: end_date = ymdToLocalDate(hw.end_date)
		const endDate   = hw.end_date ? ymdToLocalDate( hw.end_date ) : null;
		// Mirror: ci_end_date = removeDays(end_date, minNight)
		const ciEndDate = endDate ? addDays( endDate, -minNight ) : null;
		// Mirror: co_start_date = addDays(start_date, minNight) — adjusted if checkin already set
		const existingCheckin = search.checkin ? ymdToLocalDate( search.checkin ) : null;
		const coStartDate     = addDays( existingCheckin ?? startDate, minNight );

		// Declare with let so closures in onSelect can reference both instances
		let dpIn, dpOut;

		// ── Check-out picker (declared first so checkin's onSelect can reference it) ──
		dpOut = new window.AirDatepicker( checkoutAnchorRef.current, {
			selectedDates: search.checkout ? [ ymdToLocalDate( search.checkout ) ] : [],
			locale,
			minDate:        coStartDate,
			...( endDate && { maxDate: endDate } ),
			autoClose:      true,
			toggleSelected: false,
			onSelect: ( { date } ) => {
				if ( ! date ) return;

				setCheckoutError( null );

				const checkinDate  = dpIn.selectedDates[ 0 ];
				const checkoutDate = date;

				// Mirror: if checkout <= checkin → push checkout to checkin + 1
				if ( checkinDate && checkoutDate <= checkinDate ) {
					dpOut.selectDate( addDays( checkinDate, 1 ) );
					return;
				}

				// Mirror: if stay < minNight → push checkout to checkin + minNight, show error
				if ( checkinDate ) {
					const days = ( checkoutDate - checkinDate ) / ( 1000 * 3600 * 24 );
					if ( Math.ceil( days ) < minNight ) {
						dpOut.selectDate( addDays( checkinDate, minNight ) );
						setCheckoutError(
							window[ 'messages' ]?.checkout_min_nights
							?? `Minimum stay is ${ minNight } night${ minNight !== 1 ? 's' : '' }.`
						);
						return;
					}
				}

				dispatch( { type: 'SET_SEARCH', payload: { checkout: toYmd( date ) } } );
			},
		} );

		// ── Check-in picker ────────────────────────────────────────────────────
		dpIn = new window.AirDatepicker( checkinAnchorRef.current, {
			selectedDates: search.checkin ? [ ymdToLocalDate( search.checkin ) ] : [],
			locale,
			minDate:        startDate,
			...( ciEndDate && { maxDate: ciEndDate } ),
			autoClose:      true,
			toggleSelected: false,
			onSelect: ( { date } ) => {
				if ( ! date ) return;

				dispatch( { type: 'SET_SEARCH', payload: { checkin: toYmd( date ) } } );

				// Mirror: advance date by minNight → this is the minimum checkout date
				const minCheckout     = addDays( date, minNight );
				const currentCheckout = dpOut.selectedDates[ 0 ];

				// Mirror: if checkout is empty or before minCheckout → auto-select minCheckout
				if ( ! currentCheckout || currentCheckout <= minCheckout ) {
					dpOut.selectDate( minCheckout );
				}

				// Mirror: update checkout's minDate and open it
				dpOut.update( { minDate: minCheckout } );
				dpOut.show();
			},
		} );

		dpInRef.current  = dpIn;
		dpOutRef.current = dpOut;

		return () => {
			dpIn.destroy();
			dpOut.destroy();
		};
	}, [] ); // eslint-disable-line react-hooks/exhaustive-deps

	// ── Close guests dropdown on outside click ────────────────────────────────
	useEffect( () => {
		const handler = ( e ) => {
			if ( guestsRef.current && ! guestsRef.current.contains( e.target ) ) {
				setGuestsOpen( false );
			}
		};
		document.addEventListener( 'mousedown', handler );
		return () => document.removeEventListener( 'mousedown', handler );
	}, [] );

	function adjustGuest( field, delta ) {
		const min    = field === 'adults' ? 1 : 0;
		const newVal = Math.max( min, ( search[ field ] || 0 ) + delta );
		dispatch( { type: 'SET_SEARCH', payload: { [ field ]: newVal } } );
	}

	function handleSubmit( e ) {
		e.preventDefault();
		setGuestsOpen( false );

		if ( ! search.checkin || ! search.checkout || ( search.adults || 0 ) < 1 ) {
			setSubmitAttempted( true );
			return;
		}

		// Reflect search params in the URL without adding a history entry
		const params = new URLSearchParams( window.location.search );
		params.set( 'checkin',  search.checkin );
		params.set( 'checkout', search.checkout );
		params.set( 'adults',   search.adults   ?? 1 );
		[ 'teens', 'children', 'infants' ].forEach( ( key ) => {
			const val = search[ key ] ?? 0;
			if ( val > 0 ) {
				params.set( key, val );
			} else {
				params.delete( key );
			}
		} );
		history.replaceState( null, '', `${ window.location.pathname }?${ params }` );

		setSubmitAttempted( false );
		setMobileOpen( false );
		dispatch( { type: 'RESET_BOOKING' } );
	}

	const triggerDates = search.checkin && search.checkout
		? `${ formatDate( search.checkin ) } → ${ formatDate( search.checkout ) }`
		: 'Select dates';

	return (
		<>
		{ /* ── Mobile trigger (hidden on desktop via CSS) ── */ }
		<div className="sb-mobile-trigger" onClick={ () => setMobileOpen( true ) }>
			<div className="sb-trigger__icon">
				<i className="fas fa-search" />
			</div>
			<div className="sb-trigger__info">
				<div className="sb-trigger__dates">{ triggerDates }</div>
				<div className="sb-trigger__sub">{ HOTEL_NAME } · { guestSummary( search ) }</div>
			</div>
		</div>

		{ /* ── Backdrop ── */ }
		{ mobileOpen && (
			<div className="sb-mobile-backdrop" onClick={ () => setMobileOpen( false ) } />
		) }

		<form className={ `sb-wrap${ mobileOpen ? ' sb-wrap--open' : '' }` } onSubmit={ handleSubmit }>
			{ /* ── Mobile form header ── */ }
			<div className="sb-mobile-header">
				<span className="sb-mobile-header__title">Edit Search</span>
				<button type="button" className="sb-mobile-header__close" onClick={ () => setMobileOpen( false ) }>
					<i className="fas fa-times" />
				</button>
			</div>

			<div className="sb-bar">

				{ /* ── Hotel ── */ }
				<div className="sb-field sb-field--hotel">
					<span className="sb-label">
						<i className="fas fa-map-marker-alt" />
						Hotel
					</span>
					<span className="sb-value">Grand Velas Riviera Maya</span>
				</div>

				{ /* ── Check-in ── */ }
				<div
					className={ `sb-field sb-field--dates${ checkinInvalid ? ' sb-field--invalid' : '' }` }
					onClick={ () => dpInRef.current?.show() }
					role="button"
					tabIndex={ 0 }
					onKeyDown={ ( e ) => e.key === 'Enter' && dpInRef.current?.show() }
				>
					{ /* Hidden anchor — AirDatepicker positions its popup relative to this */ }
					<input ref={ checkinAnchorRef } type="text" className="sb-anchor" readOnly />
					<span className="sb-label">
						<i className="fas fa-calendar-alt" />
						Check-in
					</span>
					<span className={ `sb-value${ ! search.checkin ? ' sb-value--empty' : '' }` }>
						{ search.checkin ? formatDate( search.checkin ) : 'Select date' }
					</span>
				</div>

				{ /* ── Check-out ── */ }
				<div
					className={ `sb-field sb-field--dates${ checkoutInvalid ? ' sb-field--invalid' : '' }` }
					onClick={ () => dpOutRef.current?.show() }
					role="button"
					tabIndex={ 0 }
					onKeyDown={ ( e ) => e.key === 'Enter' && dpOutRef.current?.show() }
				>
					{ /* Hidden anchor — AirDatepicker positions its popup relative to this */ }
					<input ref={ checkoutAnchorRef } type="text" className="sb-anchor" readOnly />
					<span className="sb-label">Check-out</span>
					<span className={ `sb-value${ ! search.checkout ? ' sb-value--empty' : '' }` }>
						{ search.checkout ? formatDate( search.checkout ) : 'Select date' }
					</span>
					{ checkoutError && (
						<span className="sb-field-error">{ checkoutError }</span>
					) }
				</div>

				{ /* ── Guests ── */ }
				<div ref={ guestsRef } className={ `sb-field sb-field--guests${ guestsInvalid ? ' sb-field--invalid' : '' }` }>
					<div
						className="sb-guests-trigger"
						onClick={ () => setGuestsOpen( ( v ) => ! v ) }
						role="button"
						tabIndex={ 0 }
						onKeyDown={ ( e ) => e.key === 'Enter' && setGuestsOpen( ( v ) => ! v ) }
					>
						<span className="sb-label">
							<i className="fas fa-user-friends" />
							Guests
						</span>
						<span className="sb-value">{ guestSummary( search ) }</span>
					</div>

					{ guestsOpen && (
						<div className="sb-guests-dropdown">
							{ GUEST_TYPES.map( ( { field, label, desc, min } ) => (
								<div key={ field } className="sb-guest-row">
									<div>
										<div className="sb-guest-label">{ label }</div>
										<div className="sb-guest-desc">{ desc }</div>
									</div>
									<div className="sb-guest-counter">
										<button
											type="button"
											className="sb-counter-btn"
											onClick={ () => adjustGuest( field, -1 ) }
											disabled={ ( search[ field ] || 0 ) <= min }
										>−</button>
										<span className="sb-counter-val">{ search[ field ] || 0 }</span>
										<button
											type="button"
											className="sb-counter-btn"
											onClick={ () => adjustGuest( field, +1 ) }
										>+</button>
									</div>
								</div>
							) ) }
						</div>
					) }
				</div>

				{ /* ── Search button ── */ }
				<div className="sb-action">
					<button type="submit" className="sb-search-btn" title="Search">
						<i className="fas fa-search" />
					</button>
				</div>

			</div>

			</form>
		</>
	);
}
