import { useState }       from '@wordpress/element';
import { useBooking }     from '../../hooks/useBooking';
import { useCart }        from '../../hooks/useCart';
import { submitQuote }    from '../../api/booking';
import { StepCard }       from '../StepCard';
import DepositCard        from './review/DepositCard';
import CardDetailsCard    from './review/CardDetailsCard';
import DisclaimerCard     from './review/DisclaimerCard';
import CancellationCard  from './review/CancellationCard';
import PaymentPolicyCard from './review/PaymentPolicyCard';
import Dialog             from '../Dialog';

const IS_PAYMENT_ENABLED = Boolean( window.hwBooking?.isPaymentEnabled );
const INSURANCE_PLANS    = window.hwBooking?.insuranceData?.plans ?? [];
const CURRENCY           = window.hwBooking?.currency ?? 'USD';
const STEP_BILLING       = 2;

function formatPrice( amount ) {
	return new Intl.NumberFormat( 'en-US', { style: 'currency', currency: CURRENCY } ).format( amount );
}

function validatePayment( payment, { isAmex, cvvLength, cardLength, grandTotal, minDepositAmount } ) {
	const errors = {};
	const cardOwner     = ( payment.cardOwner  ?? '' ).trim();
	const cardNumber    = ( payment.cardNumber  ?? '' ).replace( /\D/g, '' );
	const cardMonth     = String( payment.cardMonth ?? '' ).trim();
	const cardYear      = String( payment.cardYear  ?? '' ).trim();
	const cvv           = String( payment.cvv       ?? '' ).trim();
	const depositType   = payment.depositType ?? 'deposit';
	const depositAmount = Number( payment.depositAmount ?? minDepositAmount );

	if ( ! cardOwner )                           errors.cardOwner  = 'Card owner is required.';
	if ( ! cardNumber )                          errors.cardNumber = 'Card number is required.';
	else if ( cardNumber.length !== cardLength ) errors.cardNumber = `Card number must be ${ cardLength } digits.`;

	if ( ! cardMonth || ! cardYear )             errors.expiry = 'Expiration date is required.';
	else if ( !/^\d{1,2}$/.test( cardMonth ) || +cardMonth < 1 || +cardMonth > 12 )
	                                             errors.expiry = 'Enter a valid month (1–12).';
	else if ( !/^\d{4}$/.test( cardYear ) || +cardYear < new Date().getFullYear() )
	                                             errors.expiry = 'Enter a valid 4-digit year.';

	if ( ! cvv )                                 errors.cvv = `${ isAmex ? 'CID' : 'CVV' } is required.`;
	else if ( cvv.length !== cvvLength )         errors.cvv = `${ isAmex ? 'CID' : 'CVV' } must be ${ cvvLength } digits.`;

	if ( depositType === 'custom' && depositAmount < minDepositAmount )
	                                             errors.depositAmount = `Minimum amount is ${ formatPrice( minDepositAmount ) }.`;

	if ( ! payment.acceptCharge )                errors.acceptCharge = 'You must authorize the charge to continue.';

	return errors;
}

function validateDisclaimer( payment ) {
	const errors = {};
	if ( ! payment.termsAccepted ) errors.termsAccepted = 'Please read and accept the Terms & Conditions.';
	if ( ! payment.signature     ) errors.signature     = 'Please add your electronic signature.';
	return errors;
}

export default function StepReview() {
	const booking = useBooking();
	const { grandTotal, minDepositAmount, deposit, isRoomAvailable } = useCart();

	const [ loading,    setLoading    ] = useState( false );
	const [ dialog,     setDialog     ] = useState( null );
	const [ showErrors, setShowErrors ] = useState( false );

	const { billing, payment, dispatch, prevStep } = booking;

	const cardType      = payment.cardType    ?? 'visa';
	const isAmex        = cardType === 'amex';
	const cvvLength     = isAmex ? 4 : 3;
	const cardLength    = isAmex ? 15 : 16;
	const depositType   = payment.depositType ?? 'deposit';
	const payableAmount = depositType === 'deposit' ? deposit
		: depositType === 'full'   ? grandTotal
		: Number( payment.depositAmount ?? minDepositAmount );

	const needsPaymentValidation = IS_PAYMENT_ENABLED && isRoomAvailable;

	const payErrors  = showErrors && needsPaymentValidation
		? validatePayment( payment, { isAmex, cvvLength, cardLength, grandTotal, minDepositAmount } )
		: {};
	const discErrors = showErrors && IS_PAYMENT_ENABLED
		? validateDisclaimer( payment )
		: {};

	const isUS             = billing?.country?.toUpperCase() === 'US';
	const insuranceSkipped = ! isUS || INSURANCE_PLANS.length === 0;

	function handleBack() {
		if ( insuranceSkipped ) {
			dispatch( { type: 'SET_STEP', payload: STEP_BILLING } );
		} else {
			prevStep();
		}
	}

	async function handleSubmit( e ) {
		e.preventDefault();
		setShowErrors( true );

		const pe = needsPaymentValidation
			? validatePayment( payment, { isAmex, cvvLength, cardLength, grandTotal, minDepositAmount } )
			: {};
		const de = IS_PAYMENT_ENABLED ? validateDisclaimer( payment ) : {};

		if ( Object.keys( pe ).length > 0 || Object.keys( de ).length > 0 ) return;

		setLoading( true );
		try {
			await submitQuote( {
				checkin:         booking.search.checkin,
				checkout:        booking.search.checkout,
				adults:          booking.search.adults,
				teens:           booking.search.teens,
				children:        booking.search.children,
				infants:         booking.search.infants,
				roomBlockId:     booking.selectedRoom?.id ?? null,
				packageId:       booking.selectedPackage?.id ?? null,
				insurancePlanId: booking.insurance?.planId ?? 0,
				notes:           booking.notes,
				customer: {
					firstName: booking.billing.firstName,
					lastName:  booking.billing.lastName,
					email:     booking.billing.email,
					phone:     booking.billing.phone,
					address:   booking.billing.address,
					city:      booking.billing.city,
					state:     booking.billing.state,
					country:   booking.billing.country,
					zip:       booking.billing.zip,
				},
				guests: booking.guests.map( g => ( {
					title:      g.title,
					name:       g.name,
					lastname:   g.lastname,
					personType: g.personType,
					dob:        { day: g.day, month: g.month, year: g.year },
				} ) ),
				payment: {
					cardType:      booking.payment.cardType,
					cardOwner:     booking.payment.cardOwner,
					cardNumber:    booking.payment.cardNumber,
					cardMonth:     booking.payment.cardMonth,
					cardYear:      booking.payment.cardYear,
					cvv:           booking.payment.cvv,
					depositType:   booking.payment.depositType,
					depositAmount: booking.payment.depositType === 'custom' ? booking.payment.depositAmount : null,
					acceptCharge:  booking.payment.acceptCharge,
				},
				termsAccepted: Boolean( booking.payment.termsAccepted ),
				signature:     booking.payment.signature ?? null,
			} );
			setDialog( {
				type:    'success',
				title:   'Booking Request Submitted!',
				message: 'Your request has been received. Our team will be in touch shortly to confirm your reservation.',
			} );
		} catch ( err ) {
			setDialog( {
				type:    'error',
				title:   'Submission Failed',
				message: err?.message ?? 'Something went wrong. Please try again.',
			} );
		} finally {
			setLoading( false );
		}
	}

	return (
		<div>
			<Dialog
				open={ dialog !== null }
				type={ dialog?.type }
				title={ dialog?.title }
				message={ dialog?.message }
				onClose={ () => setDialog( null ) }
			/>

			{ IS_PAYMENT_ENABLED && (
				<>
					{ isRoomAvailable ? (
						<>
							<DepositCard     errors={ payErrors } />
							<CardDetailsCard errors={ payErrors } payableAmount={ formatPrice( payableAmount ) } />
						</>
					) : (
						<StepCard className="mb-3">
							<div className="alert alert-info mb-0 d-flex align-items-start gap-2" role="alert">
								<i className="fas fa-info-circle mt-1 flex-shrink-0" />
								<div>
									<strong>Room requires confirmation.</strong> This room is subject to availability.
									An agent will contact you to confirm your reservation before any payment is collected.
								</div>
							</div>
						</StepCard>
					) }

					<CancellationCard />
					<PaymentPolicyCard />
					<DisclaimerCard errors={ discErrors } />
				</>
			) }

			<form onSubmit={ handleSubmit }>
				<div className="d-flex justify-content-between">
					<button type="button" className="btn btn-secondary" onClick={ handleBack }>
						<i className="fas fa-arrow-left" />
						Back
					</button>
					<button type="submit" className="btn btn-success" disabled={ loading }>
						{ loading
							? <>Submitting… <i className="fas fa-spinner fa-spin" /></>
							: <>Submit Booking <i className="far fa-calendar-check" /></>
						}
					</button>
				</div>
			</form>
		</div>
	);
}
