import { createContext, useContext, useReducer } from '@wordpress/element';

const BookingContext = createContext( null );

// Read search params from URL on page load
const _p       = new URLSearchParams( window.location.search );
const _checkin  = _p.get( 'checkin' )  ?? '';
const _checkout = _p.get( 'checkout' ) ?? '';
const _adults   = Math.max( 1, parseInt( _p.get( 'adults'   ) ?? 1 ) );
const _teens    = Math.max( 0, parseInt( _p.get( 'teens'    ) ?? 0 ) );
const _children = Math.max( 0, parseInt( _p.get( 'children' ) ?? 0 ) );
const _infants  = Math.max( 0, parseInt( _p.get( 'infants'  ) ?? 0 ) );
const _hasSearch = Boolean( _checkin && _checkout );

const initialState = {
	step:          0,
	searchVersion: _hasSearch ? 1 : 0,
	searched:      _hasSearch,
	search: {
		checkin:  _checkin,
		checkout: _checkout,
		adults:   _adults,
		teens:    _teens,
		children: _children,
		infants:  _infants,
	},
	selectedRoom:    null,
	selectedPackage: null,
	guests:          [],
	billing:         {},
	insurance:       null,
	payment:         { depositType: 'deposit' },
	notes:           '',
};

function reducer( state, action ) {
	switch ( action.type ) {
		case 'SET_SEARCHED':
			return { ...state, searched: true };
		case 'RESET_BOOKING':
			return {
				...state,
				searched:        true,
				searchVersion:   state.searchVersion + 1,
				step:            0,
				selectedRoom:    null,
				selectedPackage: null,
				guests:          [],
				billing:         {},
				insurance:       null,
				payment:         { depositType: 'deposit' },
				notes:           '',
			};
		case 'SET_STEP':
			return { ...state, step: action.payload };
		case 'NEXT_STEP':
			return { ...state, step: state.step + 1 };
		case 'PREV_STEP':
			return { ...state, step: Math.max( 0, state.step - 1 ) };
		case 'SET_SEARCH':
			return { ...state, search: { ...state.search, ...action.payload } };
		case 'SET_ROOM':
			return { ...state, selectedRoom: action.payload };
		case 'SET_PACKAGE':
			return { ...state, selectedPackage: action.payload };
		case 'SET_GUESTS':
			return { ...state, guests: action.payload };
		case 'SET_BILLING':
			return { ...state, billing: { ...state.billing, ...action.payload } };
		case 'SET_INSURANCE':
			return { ...state, insurance: action.payload };
		case 'SET_PAYMENT':
			return { ...state, payment: { ...state.payment, ...action.payload } };
		case 'SET_NOTES':
			return { ...state, notes: action.payload };
		case 'FILL_MOCK':
			return { ...state, ...action.payload };
		default:
			return state;
	}
}

export function BookingProvider( { children } ) {
	const [ state, dispatch ] = useReducer( reducer, initialState );

	return (
		<BookingContext.Provider value={ { ...state, dispatch } }>
			{ children }
		</BookingContext.Provider>
	);
}

export function useBooking() {
	const ctx = useContext( BookingContext );
	if ( ! ctx ) throw new Error( 'useBooking must be used inside BookingProvider' );
	return ctx;
}
