const _state = {
	testMode:     false,
	mockOutcome:  'success',
	lastPayload:  null,
	lastResponse: null,
};

const _listeners = new Set();

function _notify() {
	const snap = { ..._state };
	_listeners.forEach( fn => fn( snap ) );
}

export const devStore = {
	get()           { return { ..._state }; },
	set( patch )    { Object.assign( _state, patch ); _notify(); },
	subscribe( fn ) { _listeners.add( fn ); return () => _listeners.delete( fn ); },
};
