import { useBooking } from '../hooks/useBooking';

const STEPS = [
	{ label: 'Room',      icon: 'fa-bed'            },
	{ label: 'Guests',    icon: 'fa-users'           },
	{ label: 'Contact',   icon: 'fa-address-card'    },
	{ label: 'Insurance', icon: 'fa-shield-alt'      },
	{ label: 'Review',    icon: 'fa-clipboard-check' },
];

export default function StepProgress() {
	const { step } = useBooking();

	return (
		<div className="sp-wrap">
			{ STEPS.map( ( { label, icon }, i ) => {
				const isPast    = i < step;
				const isCurrent = i === step;

				return (
					<div
						key={ i }
						className={ `sp-bar${ isPast ? ' sp-bar--done' : '' }${ isCurrent ? ' sp-bar--active' : '' }` }
					>
						<span className="sp-bar__num">
							{ isPast
								? <i className="fas fa-check" />
								: <i className={ `fas ${ icon }` } />
							}
						</span>
						<span className="sp-bar__label">{ label }</span>
					</div>
				);
			} ) }
		</div>
	);
}
