import { useState }    from '@wordpress/element';
import { useBooking } from '../../hooks/useBooking';
import { StepCard }   from '../StepCard';
import COUNTRIES from '../../../../includes/data/countries.json';
import STATES    from '../../../../includes/data/states.json';

const US_STATES = Object.entries( STATES.US ).map( ( [ code, name ] ) => ( { code, name } ) );

const FIELDS = [
	{ name: 'firstName', label: 'First Name', col: 'col-md-6' },
	{ name: 'lastName',  label: 'Last Name',  col: 'col-md-6' },
	{ name: 'email',     label: 'Email',      col: 'col-md-6', type: 'email' },
	{ name: 'phone',     label: 'Phone',      col: 'col-md-6', type: 'tel' },
	{ name: 'address',   label: 'Address',    col: 'col-md-9' },
	{ name: 'zip',       label: 'ZIP',        col: 'col-md-3' },
	{ name: 'city',      label: 'City',       col: 'col-md-5' },
];

function validate( billing, isUS ) {
	const errors = {};

	FIELDS.forEach( ( { name } ) => {
		if ( ! ( billing[ name ] ?? '' ).trim() ) errors[ name ] = 'This field is required.';
	} );

	if ( billing.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test( billing.email ) ) {
		errors.email = 'Enter a valid email address.';
	}

	if ( ! ( billing.country ?? '' ) ) {
		errors.country = 'Please select a country.';
	}

	// State is always required — dropdown for US, free text for others
	if ( ! ( billing.state ?? '' ).trim() ) {
		errors.state = isUS ? 'Please select a state.' : 'This field is required.';
	}

	return errors;
}

export default function StepBilling() {
	const { billing, dispatch, nextStep, prevStep } = useBooking();
	const [ showErrors, setShowErrors ] = useState( false );

	const isUS   = billing.country === 'US';
	const errors = showErrors ? validate( billing, isUS ) : {};

	function set( field ) {
		return ( e ) => dispatch( { type: 'SET_BILLING', payload: { [ field ]: e.target.value } } );
	}

	function handleCountryChange( e ) {
		dispatch( { type: 'SET_BILLING', payload: { country: e.target.value, state: '' } } );
	}

	function handleNext() {
		setShowErrors( true );
		if ( Object.keys( validate( billing, isUS ) ).length === 0 ) nextStep();
	}

	function fc( key ) {
		return `form-control${ errors[ key ] ? ' is-invalid' : '' }`;
	}

	return (
		<div>
		<StepCard className="mb-3">
			<StepCard.Header icon="fas fa-user" title="Main Contact Information" />

			<div className="form-row">
				{ FIELDS.map( ( { name, label, col, type = 'text' } ) => (
					<div key={ name } className={ `form-group ${ col }` }>
						<label>{ label }</label>
						<input
							type={ type }
							className={ fc( name ) }
							value={ billing[ name ] ?? '' }
							onChange={ set( name ) }
						/>
						{ errors[ name ] && (
							<div className="invalid-feedback">{ errors[ name ] }</div>
						) }
					</div>
				) ) }

				{ /* State — dropdown for US, free text for all other countries */ }
				<div className="form-group col-md-3">
					<label>State</label>
					{ isUS ? (
						<>
							<select
								className={ fc( 'state' ) }
								value={ billing.state ?? '' }
								onChange={ set( 'state' ) }
							>
								{ US_STATES.map( ( { code, name } ) => (
									<option key={ code } value={ code }>{ name }</option>
								) ) }
							</select>
							{ errors.state && <div className="invalid-feedback">{ errors.state }</div> }
						</>
					) : (
						<>
							<input
								type="text"
								className={ fc( 'state' ) }
								value={ billing.state ?? '' }
								onChange={ set( 'state' ) }
							/>
							{ errors.state && <div className="invalid-feedback">{ errors.state }</div> }
						</>
					) }
				</div>

				<div className="form-group col-md-4">
					<label>Country</label>
					<select
						className={ fc( 'country' ) }
						value={ billing.country ?? '' }
						onChange={ handleCountryChange }
					>
						<optgroup label="Most Used">
							<option value="US">United States</option>
						</optgroup>
						<optgroup label="All Countries">
							{ COUNTRIES.filter( ( { code } ) => code !== 'US' ).map( ( { name, code } ) => (
								<option key={ code } value={ code }>{ name }</option>
							) ) }
						</optgroup>
					</select>
					{ errors.country && <div className="invalid-feedback">{ errors.country }</div> }
				</div>
			</div>

		</StepCard>

		<div className="mt-3 d-flex justify-content-between">
			<button type="button" className="btn btn-secondary" onClick={ prevStep }>
				<i className="fas fa-arrow-left" />
				Back
			</button>
			<button type="button" className="btn btn-primary" onClick={ handleNext }>
				Next
				<i className="fas fa-arrow-right" />
			</button>
		</div>
		</div>
	);
}
